import unicodedata

from django.db import migrations, models

MOTIVO_OPERACAO = ("Acompanhar a operação policial, prestando assessoria de imprensa, atendimento "
                   "aos veículos de comunicação e suporte de comunicação.")


def _chave(nome: str) -> str:
    sem = "".join(c for c in unicodedata.normalize("NFD", nome)
                  if unicodedata.category(c) != "Mn")
    return " ".join(sem.lower().replace("-", " ").split())


def ligar_tipos(apps, schema_editor):
    """Tipos de viagem já cadastrados com nome de tipo de OS passam a trazer o tipo (e, na
    operação policial, o motivo), se ainda não tiverem."""
    TipoViagem = apps.get_model("cadastros", "TipoViagem")
    for tipo in TipoViagem.objects.filter(tipo_os=""):
        nome = _chave(tipo.nome)
        if "operacao policial" in nome:
            tipo.tipo_os = "operacao_policial"
            tipo.motivo = tipo.motivo or MOTIVO_OPERACAO
        elif "unidade movel" in nome:
            tipo.tipo_os = "unidade_movel"
        elif "cerimonial" in nome:
            tipo.tipo_os = "cerimonial"
        else:
            continue
        tipo.save(update_fields=["tipo_os", "motivo"])


